print(">>> 1. Ensuring Categories...");
const categories = [
  { title: 'SSC 2027', slug: 'ssc-2027' },
  { title: 'SSC 2028', slug: 'ssc-2028' },
  { title: 'কম্বো কোর্স', slug: 'combo-courses' },
  { title: 'ফ্রি কোর্স', slug: 'free-courses' },
];
const categoryMap = {};
for (const cat of categories) {
  let existing = db.categories.findOne({ $or: [{ slug: cat.slug }, { title: cat.title }] });
  if (!existing) {
    const res = db.categories.insertOne({ title: cat.title, slug: cat.slug, createdAt: new Date(), updatedAt: new Date() });
    categoryMap[cat.slug] = res.insertedId;
  } else {
    categoryMap[cat.slug] = existing._id;
    db.categories.updateOne({ _id: existing._id }, { $set: { title: cat.title, slug: cat.slug, updatedAt: new Date() } });
  }
}

