let newUsersCount = 0;
const bulkUsers = [];
for (const u of usersList) {
  if (!userMap[u.email]) {
    bulkUsers.push({
      email: u.email,
      name: u.name,
      phone: u.phone,
      role: u.role,
      emailVerified: false,
      createdAt: u.registeredAt ? new Date(u.registeredAt) : new Date(),
      updatedAt: new Date(),
    });
  }
}
if (bulkUsers.length > 0) {
  const insertRes = db.users.insertMany(bulkUsers);
  newUsersCount = bulkUsers.length;
  db.users.find({}, { _id: 1, email: 1 }).forEach(u => {
    if (u.email) userMap[u.email.toLowerCase().trim()] = u._id;
  });
}
print("Users synced: New users added: " + newUsersCount + ", Total in map: " + Object.keys(userMap).length);

print(">>> 7. Migrating Student Enrollments...");
const productMap = {};
db.products.find({}, { _id: 1, legacyId: 1, title: 1 }).forEach(p => {
  if (p.legacyId) productMap[p.legacyId] = p._id;
  if (p.title) productMap[p.title.trim()] = p._id;
});

const existingEnr = new Set();
db.enrollments.find({}, { student: 1, course: 1 }).forEach(e => {
  if (e.student && e.course) {
    existingEnr.add(e.student.toString() + '_' + e.course.toString());
  }
});

