const bulkEnr = [];
let skippedEnr = 0;
for (const enr of enrollmentsList) {
  const studentId = userMap[enr.email];
  const courseId = productMap[enr.courseId] || productMap[enr.courseTitle.trim()];
  if (!studentId || !courseId) {
    skippedEnr++;
    continue;
  }
  const key = studentId.toString() + '_' + courseId.toString();
  if (!existingEnr.has(key)) {
    existingEnr.add(key);
    bulkEnr.push({
      student: studentId,
      course: courseId,
      status: 'active',
      completedLessons: [],
      enrolledAt: enr.enrolledAt ? new Date(enr.enrolledAt) : new Date(),
      createdAt: enr.enrolledAt ? new Date(enr.enrolledAt) : new Date(),
      updatedAt: new Date(),
    });
  }
}
if (bulkEnr.length > 0) {
  db.enrollments.insertMany(bulkEnr);
}
print("Enrollments synced: Inserted " + bulkEnr.length + ", Skipped (unmatched or exists): " + skippedEnr + ", Total now: " + db.enrollments.countDocuments());

print("\n=== MIGRATION COMPLETED SUCCESSFULLY! ===");